<?php
namespace Ishep\Http\Controllers;use Ishep\Bootstrap\Application as App;use Ishep\Http\{Request,Response};final class PublicController{public function page(string $view,array $data=[]):Response{return App::instance()->render($view,$data);}public function verifyMembership(Request $request):Response{$number=strtoupper(trim((string)($request->query['number']??'')));$result=null;$searched=false;if($number!==''){$searched=true;$key='verify:'.hash('sha256',$number.'|'.$request->ip());if(!App::instance()->limiter()->blocked($key)){App::instance()->limiter()->hit($key);if(preg_match('/^ISH-MEM-\d{4}-[A-F0-9]{16}$/',$number))$result=App::instance()->finance()->verifiedMembership($number);}else{$result=['throttled'=>true];}}return App::instance()->render('public/verify-membership',['number'=>$number,'result'=>$result,'searched'=>$searched]);}public function health(Request $r):Response{$ok=true;try{App::instance()->db()->query('SELECT 1');}catch(\Throwable){$ok=false;}return Response::json(['status'=>$ok?'ok':'degraded','php'=>PHP_VERSION,'database'=>$ok?'reachable':'not reachable','environment'=>App::instance()->config('app.env')],$ok?200:503);}}
